  var pageTitle = {vi:"Garment Academy | Máy móc và thiết bị ngành may", en:"Garment Academy | Garment Machinery and Equipment"};
  var pageDescription = {vi:"Chuyên đề máy may công nghiệp, cơ cấu tạo mũi, cấp liệu, kim, chỉ, thiết lập, bảo trì và an toàn vận hành.", en:"A technical reference to industrial sewing machines, stitch formation, feeding systems, needles, thread, setup, maintenance and safe operation."};
  var dictionary = Object.create(null), index = 0;
  function makeKey(kind){ index += 1; return 'phase7.' + kind + '.' + index; }
  function translatedValue(source){
    var leading=(source.match(/^\s*/) || [''])[0], trailing=(source.match(/\s*$/) || [''])[0];
    var trimmed=source.replace(/\\s+/g,' ').trim();
    if(!Object.prototype.hasOwnProperty.call(translations,trimmed)) return null;
    return {leading:leading,trailing:trailing,value:translations[trimmed]};
  }
  function makeTablesScrollable(){
    document.querySelectorAll('table').forEach(function(table){
      if(table.closest('.bilingual-table-scroll')) return;
      var wrapper=document.createElement('div');
      wrapper.className='bilingual-table-scroll';
      table.parentNode.insertBefore(wrapper,table);
      wrapper.appendChild(table);
    });
  }
  function annotateText(){
    var walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT), nodes=[], node;
    while((node=walker.nextNode())) nodes.push(node);
    nodes.forEach(function(textNode){
      var parent=textNode.parentElement;
      if(!parent || /^(SCRIPT|STYLE|NOSCRIPT|TEMPLATE)$/.test(parent.tagName)) return;
      if(parent.closest && parent.closest('[data-i18n]')) return;
      var result=translatedValue(textNode.nodeValue);
      if(!result) return;
      var k=makeKey('text'); dictionary[k]=result.leading+result.value+result.trailing;
      if(parent.namespaceURI==='http://www.w3.org/2000/svg'){
        if(/^(text|tspan|title)$/i.test(parent.tagName) && parent.childNodes.length===1) parent.setAttribute('data-i18n',k);
        else { var span=document.createElementNS('http://www.w3.org/2000/svg','tspan'); span.setAttribute('data-i18n',k); span.textContent=textNode.nodeValue; parent.replaceChild(span,textNode); }
      } else { var span=document.createElement('span'); span.setAttribute('data-i18n',k); span.textContent=textNode.nodeValue; parent.replaceChild(span,textNode); }
    });
  }
  function annotateAttributes(){
    ['title','placeholder','aria-label','alt'].forEach(function(attr){
      document.body.querySelectorAll('*').forEach(function(el){
        var source=el.getAttribute(attr); if(!source) return;
        var result=translatedValue(source); if(!result) return;
        var k=makeKey('attr'); dictionary[k]=result.value;
        if(attr==='alt'){el.setAttribute('data-i18n-alt',k);el.setAttribute('data-i18n-source-alt',source);}
        else el.setAttribute('data-i18n-'+attr,k);
      });
    });
  }
  function updateDynamicCount(){
    var count=document.getElementById('count');
    if(!count) return;
    var raw=count.textContent||'', match=raw.match(/(\d+)\s*\/\s*(\d+)/);
    if(!match){
      var cards=Array.prototype.slice.call(document.querySelectorAll('.lesson'));
      if(!cards.length) return;
      var visible=cards.filter(function(card){return !card.hidden;}).length;
      match=[null,String(visible),String(cards.length)];
    }
    var lang=window.AppNhoI18n?window.AppNhoI18n.getLanguage():'vi';
    var desired=lang==='en' ? ('Showing '+match[1]+'/'+match[2]+' lessons') : ('Đang hiển thị '+match[1]+'/'+match[2]+' bài học');
    if(raw!==desired) count.textContent=desired;
  }
  function updateMeta(){
    var lang=window.AppNhoI18n?window.AppNhoI18n.getLanguage():'vi';
    document.title=pageTitle[lang]||pageTitle.vi;
    var meta=document.querySelector('meta[name="description"]');
    if(meta) meta.setAttribute('content',pageDescription[lang]||pageDescription.vi);
    updateDynamicCount();
    document.body.querySelectorAll('[data-i18n-alt]').forEach(function(el){
      var k=el.getAttribute('data-i18n-alt');
      el.setAttribute('alt',lang==='en' && Object.prototype.hasOwnProperty.call(dictionary,k)?dictionary[k]:(el.getAttribute('data-i18n-source-alt')||''));
    });
  }
  makeTablesScrollable();
  annotateText(); annotateAttributes();
  if(window.AppNhoI18n){ window.AppNhoI18n.register('en',dictionary); window.AppNhoI18n.setPageReady(true); }
  updateMeta();
  var countNode=document.getElementById('count');
  if(countNode && window.MutationObserver){
    var countObserver=new MutationObserver(updateDynamicCount);
    countObserver.observe(countNode,{childList:true,characterData:true,subtree:true});
  }
  window.addEventListener('appnho:languagechange',updateMeta);
  document.addEventListener('DOMContentLoaded',updateMeta,{once:true});
